package com.northstar.crm.service;
import com.northstar.crm.domain.*;import com.northstar.crm.repo.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.*;
@Component public class RenewalReminderJob {private final OrganizationRepository organizations;private final NotificationRepository notifications;private final AuditRepository audits;private final UserRepository users;public RenewalReminderJob(OrganizationRepository o,NotificationRepository n,AuditRepository a,UserRepository u){organizations=o;notifications=n;audits=a;users=u;}@Scheduled(cron="0 15 7 * * *",zone="UTC")@Transactional public void remind(){var system=users.findByEmailIgnoreCase("system@northstar.local").orElse(null);if(system==null)return;var from=LocalDate.now(ZoneOffset.UTC).plusDays(29);var due=organizations.findByRenewalDateBetweenOrderByRenewalDate(from,from.plusDays(1));due.forEach(o->{notifications.save(new Notification(o.getOwnerId(),"Renewal due in 30 days",o.getName()+" renews on "+o.getRenewalDate(),"organizations/"+o.getId()));audits.save(new AuditEvent(system.getId(),"RENEWAL_REMINDER_SENT","Organization",o.getId(),"{}","renewalDate="+o.getRenewalDate(),"scheduled policy: 30-day reminder"));});}}
